import React,{useState} from "react";
import { Link, useNavigate } from "react-router-dom";

const Header = () => {
  const navigate = useNavigate();
  const [showDropdown, setShowDropdown] = useState(false);
  const email = localStorage.getItem("email") || "Unknown";
  const role = localStorage.getItem("role");
  const profilePic = localStorage.getItem("profilePic"); // Get Google profile picture if available

  return (
    <header className="modern-header">
      <div className="header-container">
        <div className="logo" onClick={() => navigate('/home')}>
          INVENTORY
        </div>
        <nav className="nav-links">
          {role === "admin" && <Link to="/home">HOME</Link>}
          <Link to="/products">PRODUCTS</Link>
          <Link to="/category">CATEGORIES</Link>
          <Link to="/brand">BRANDS</Link>
        </nav>
        <button
          className="logout-btn"
          onClick={() => {
            localStorage.removeItem("token");
            localStorage.removeItem("role");
            localStorage.removeItem("name");
            localStorage.removeItem("email");
            navigate("/login");
          }}
        >
          Logout
        </button>
         <div className="profile-container" onClick={() => setShowDropdown(!showDropdown)} style={{ position: 'relative', cursor: 'pointer' }}>
        <img 
          src={profilePic || "/profile.png"} 
          alt="Profile" 
          className="profile-icon" 
          style={{ width: 40, height: 40, borderRadius: '50%', border: '2px solid #eee', objectFit: 'cover' }}
        />
        {showDropdown && (
          <div 
            className="profile-dropdown" 
            style={{ 
              position: 'absolute', 
              top: '110%', 
              right: 0, 
              background: '#fff', 
              boxShadow: '0 4px 16px rgba(0,0,0,0.12)', 
              borderRadius: 12, 
              padding: 20, 
              minWidth: 220, 
              zIndex: 1000,
              textAlign: 'center'
            }}
          >
            <img 
              src={profilePic || "/profile.png"} 
              alt="Profile" 
              style={{ width: 60, height: 60, borderRadius: '50%', marginBottom: 10, border: '2px solid #eee', objectFit: 'cover' }}
            />
            <p style={{ margin: '8px 0 4px', fontWeight: 500, color: '#333' }}>Welcome back!</p>
            <div style={{ fontSize: 15, color: '#666', marginBottom: 6 }}>Logged in as:</div>
            <strong style={{ fontSize: 16, color: '#1976d2', wordBreak: 'break-all' }}>{email}</strong>
          </div>
        )}
      </div>
      </div>

    </header>

  );
};

export default Header;
